/// Panics if a coordinate is not finite.
pub fn exact(p: &[[f64; 3]; 4]) -> Sign {
    let c = p.map(|point| point.map(Dyadic::from_f64));
    let t0 = &c[0][0] - &c[3][0];
    let t1 = &c[0][1] - &c[3][1];
    let t2 = &c[0][2] - &c[3][2];
    let t3 = &c[1][0] - &c[3][0];
    let t4 = &c[1][1] - &c[3][1];
    let t5 = &c[1][2] - &c[3][2];
    let t6 = &c[2][0] - &c[3][0];
    let t7 = &c[2][1] - &c[3][1];
    let t8 = &c[2][2] - &c[3][2];
    let t9 = &t4 * &t8;
    let t10 = &t5 * &t7;
    let t11 = &t9 - &t10;
    let t12 = &t0 * &t11;
    let t13 = &t3 * &t8;
    let t14 = &t5 * &t6;
    let t15 = &t13 - &t14;
    let t16 = &t1 * &t15;
    let t17 = &t12 - &t16;
    let t18 = &t3 * &t7;
    let t19 = &t4 * &t6;
    let t20 = &t18 - &t19;
    let t21 = &t2 * &t20;
    let det = &t17 + &t21;
    match det.sign() {
        1 => Sign::Positive,
        -1 => Sign::Negative,
        _ => Sign::Zero,
    }
}

